/* Media cards — image saturation + scale on hover */
.media-image {
  transform: scale(1);
  transition:
    filter 0.4s cubic-bezier(0.25, 0.1, 0.25, 1),
    transform 0.4s cubic-bezier(0.33, 1, 0.68, 1); /* hover-out */
  will-change: transform;
}
@media (hover: hover) and (pointer: fine) {
  .media-card:hover .media-image {
    filter: saturate(1);
    transform: scale(1.04);
    transition:
      filter 0.4s cubic-bezier(0.25, 0.1, 0.25, 1),
      transform 0.6s cubic-bezier(0.22, 1, 0.36, 1); /* hover-in */
  }
}
</style></div><div class="logo-wall-styles w-embed"><style>
/* ── CONFIG ─────────────────────────────── */
:root {
  --logo-wall-row-gap: 2rem;
  --logo-wall-offset: 5.4rem; /* top indent outer/middle columns */
}
[data-logo-wall="list"] {
  display: grid;
  row-gap: var(--logo-wall-row-gap);
  align-items: center;
  justify-items: center;
  padding-bottom: var(--logo-wall-offset);
}

/* ── Desktop / tablet: 7 cols, items on 1, 2, 6, 7 ── */
@media (min-width: 768px) {
  [data-logo-wall="list"] {
    grid-template-columns: repeat(7, 1fr);
  }
  [data-logo-wall="item"]:nth-child(4n + 1) { grid-column: 1; }
  [data-logo-wall="item"]:nth-child(4n + 2) { grid-column: 2; }
  [data-logo-wall="item"]:nth-child(4n + 3) { grid-column: 6; }
  [data-logo-wall="item"]:nth-child(4n)     { grid-column: 7; }
  /* Indent: shift the outer columns down */
  [data-logo-wall="item"]:nth-child(4n + 1),
  [data-logo-wall="item"]:nth-child(4n) {
    transform: translateY(var(--logo-wall-offset));
  }
  /* Orphan pair: exactly 2 leftover items go to cols 2 and 6 */
  [data-logo-wall="item"]:nth-child(4n + 1):nth-last-child(2) {
    grid-column: 2;
    transform: none;
  }
  [data-logo-wall="item"]:nth-child(4n + 2):nth-last-child(1) {
    grid-column: 6;
  }
}

/* ── Mobile: 3 filled columns, middle column indented ── */
@media (max-width: 767px) {
  [data-logo-wall="list"] {
    grid-template-columns: repeat(3, 1fr);
  }
  [data-logo-wall="item"]:nth-child(3n + 2) {
    transform: translateY(var(--logo-wall-offset));
  }
}
</style></div><div class="bunny-styles w-embed"><style>
/* Animation */
[data-bunny-background-init] :is(.bunny-bg__placeholder, .bunny-bg__loading) {
  transition: opacity 0.3s linear, visibility 0.3s linear;
}

/* Placeholder */
[data-bunny-background-init][data-player-status="playing"] .bunny-bg__placeholder,
[data-bunny-background-init][data-player-status="paused"] .bunny-bg__placeholder,
[data-bunny-background-init][data-player-activated="true"][data-player-status="ready"] .bunny-bg__placeholder {
  opacity: 0;
  visibility: hidden;
}

/* Play/Pause */
[data-bunny-background-init][data-player-status="playing"] .bunny-bg__play-svg,
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__play-svg {
  display: none;
}

[data-bunny-background-init][data-player-status="playing"] .bunny-bg__pause-svg,
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__pause-svg{
  display: block;
}

/* Loading */
[data-bunny-background-init][data-player-status="loading"] .bunny-bg__loading {
  opacity: 1;
  visibility: visible;
}


@media (hover: none) and (pointer: coarse) {
  .bunny-bg__sound { display: none; }
}
