<script>
let lenis;
if (Webflow.env("editor") === undefined) {
  lenis = new Lenis({
    lerp: 0.1,
    wheelMultiplier: 0.7,
    gestureOrientation: "vertical",
    syncTouch: false // native scroll on touch (default)
  });

  // if you use ScrollTrigger, drive Lenis from GSAP's ticker instead of your own raf:
  lenis.on("scroll", ScrollTrigger.update);
  gsap.ticker.add((time) => lenis.raf(time * 1000));
  gsap.ticker.lagSmoothing(0);
}
</script>
<script>
document.addEventListener("DOMContentLoaded", function() {
  const contactForm = document.getElementById("email-form");
  if (contactForm) {
    contactForm.addEventListener("submit", async function(e) {
      e.preventDefault();
      const formData = new FormData(contactForm);
      const submitBtn = contactForm.querySelector('input[type="submit"]');
      const waitText = submitBtn ? submitBtn.getAttribute("data-wait") || "Please wait..." : "Please wait...";
      const origText = submitBtn ? submitBtn.value : "Submit";
      if (submitBtn) submitBtn.value = waitText;

      try {
        const response = await fetch("{{ route('contact.submit') }}", {
          method: "POST",
          headers: {
            "X-CSRF-TOKEN": "{{ csrf_token() }}",
            "Accept": "application/json"
          },
          body: formData
        });

        const data = await response.json();
        if (response.ok && data.success) {
          contactForm.style.display = "none";
          const successDiv = document.querySelector(".contact_form_succes");
          if (successDiv) {
            successDiv.style.display = "block";
            successDiv.scrollIntoView({ behavior: 'smooth' });
          }
        } else {
          alert(data.message || "Please check your inputs.");
          if (submitBtn) submitBtn.value = origText;
        }
      } catch (err) {
        console.error("Submission error:", err);
        alert("Failed to send message. Please try again.");
        if (submitBtn) submitBtn.value = origText;
      }
    });
  }
});
</script>
